{
  "attacks": [
    {
      "id": "C1",
      "claim": "For [MessagePackObject(SuppressSourceGeneration = true)] types the analyzer reports its contract diagnostics (MsgPack004 missing key, MsgPack015 AllowPrivate required, MsgPack003 member type not serializable).",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C2",
      "claim": "Duplicate keys and mixed key kinds on a suppressed type are reported (MsgPack005) without the analyzer throwing.",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C3",
      "claim": "Behaviour for types without SuppressSourceGeneration is unchanged except that duplicate keys no longer throw; diagnostics for valid contracts are unchanged.",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C4",
      "claim": "The change fixes the cause of the 3.1.1 regression, namely analyzer member validation being skipped for suppressed types.",
      "outcome": "scenario_proposed",
      "scenario": "The diff does not modify line 1383 or any logic that skips member validation for suppressed types. The actual fix for the analyzer 'not working' is preventing unhandled exceptions (`ArgumentException` on duplicate keys) that crashed the analyzer.",
      "test_sketch": "Inspect the diff to confirm line 1383 is untouched. Run the analyzer on a suppressed type with duplicate keys without the `ContainsKey` check to observe it crashing.",
      "citations": []
    },
    {
      "id": "C5",
      "claim": "No formatter is generated for suppressed types and they still serialize at run time through the dynamic resolver.",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C6",
      "claim": "Skipping a member whose key kind does not match, and skipping a duplicate-key insert, never hides a contract violation: a diagnostic is always reported first.",
      "outcome": "scenario_proposed",
      "scenario": "The `continue` statement for mixed keys skips the rest of the loop body, and skipping the dictionary insert prevents the member from being added to `intMembers`. If other contract validations (like `AllowPrivate` or type serializability) occur later in the loop or iterate over `intMembers`, they will be skipped for this member, hiding the violation.",
      "test_sketch": "Create a type with a duplicate key where the second member has an unserializable type. Verify that `MsgPack003` is not reported for the second member because it was not added to `intMembers`.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs",
          "line": 1008,
          "quote": "continue; // The key kind does not match the other members; the diagnostic is reported, so skip this member."
        },
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/TypeCollector.cs",
          "line": 1023,
          "quote": "if (!intMembers.ContainsKey(member.IntKey))"
        }
      ]
    },
    {
      "id": "C7",
      "claim": "The README lists exactly which diagnostics are and are not reported for suppressed types: 011, 016 and 017 are not reported, and 004, 005, 015, 003, 012 are.",
      "outcome": "could_not_falsify"
    },
    {
      "id": "C8",
      "claim": "MsgPack012 (data type inaccessible to the resolver) is reported for suppressed types.",
      "outcome": "scenario_proposed",
      "scenario": "The diff does not contain line 921 or any changes related to `MsgPack012` and `suppressSourceGeneration`. The citation is fabricated and the diff does not show this diagnostic being enabled.",
      "test_sketch": "Inspect the diff to verify that line 921 is not modified.",
      "citations": []
    }
  ]
}
